"""Build JSON Schema 2020-12 contracts and explicit golden fixtures, not a claim analyzer."""
import json, hashlib
from pathlib import Path
R=Path(__file__).resolve().parents[1]
def save(p,x): (R/p).write_text(json.dumps(x,indent=2)+'\n')
def obj(props,required=None): return {'type':'object','additionalProperties':False,'properties':props,'required':list(props) if required is None else required}
def arr(items): return {'type':'array','items':items}
def enum(*v): return {'enum':list(v)}
S={'type':'string'}; I={'type':'integer'}; B={'type':'boolean'}; N={'type':'null'}; DATE={'type':'string','format':'date'}
IDS=arr(S)
MONEY={'type':'integer','minimum':0,'description':'USD integer cents, never float dollars'}
def nullable(x): return {'anyOf':[x,N]}
def fact(value):
 return obj({'value':nullable(value),'status':enum('explicit','user_reported','derived','unknown','conflicted'),'evidence_ids':IDS,'reason':nullable(S),'derivation':nullable(obj({'method':S,'input_fact_paths':IDS}))})
def schema(title,body): return {'$schema':'https://json-schema.org/draft/2020-12/schema','$id':f'https://claimbridge.example/schemas/{title}.schema.json',**body}
def ref(f): return {'$ref':f+'.schema.json'}
location=obj({'page':nullable({'type':'integer','minimum':1}),'section':S,'start_char':nullable({'type':'integer','minimum':0}),'end_char':nullable({'type':'integer','minimum':0}),'bbox':nullable(arr({'type':'number'}))})
evidence=schema('evidence',obj({'id':S,'domain':enum('user','plan','external','user_answer'),'kind':enum('policy','eob','denial','bill','authorization','correspondence','government_guidance','regulation','source_summary','answer'),'document_id':nullable(S),'source_id':nullable(S),'source_url':nullable({'type':'string','format':'uri'}),'location':location,'text':S,'text_kind':enum('verbatim','verified_paraphrase','user_statement'),'content_sha256':{'type':'string','pattern':'^[a-f0-9]{64}$'},'verification':enum('exact_match','human_reviewed','unverified'),'authority_scope':S,'accessed_at':nullable(DATE)}))
evidence['allOf']=[{'if':{'properties':{'domain':{'const':'external'}}},'then':{'properties':{'source_id':S,'source_url':{'type':'string','format':'uri'},'accessed_at':DATE}}},{'if':{'properties':{'domain':{'enum':['user','plan']}}},'then':{'properties':{'document_id':S,'location':{'properties':{'page':{'type':'integer','minimum':1}}}}}}]
save('schemas/evidence.schema.json',evidence)
save('schemas/document.schema.json',schema('document',obj({'id':S,'workspace_id':S,'filename':S,'sha256':{'type':'string','pattern':'^[a-f0-9]{64}$'},'mime':enum('application/pdf','text/plain'),'kind':enum('policy','eob','denial','bill','authorization','correspondence','unknown'),'synthetic':B,'status':enum('uploaded','extracting','ready','needs_ocr','invalid','encrypted','failed'),'pages':nullable({'type':'integer','minimum':1}),'error_code':nullable(S),'extraction_version':nullable(S)})))
patient=obj({'member_id':fact(S),'name':fact(S),'residence_state':fact(S)})
plan=obj({'id':fact(S),'funding':fact(enum('self_funded','fully_insured','unknown')),'erisa':fact(B),'grandfathered':fact(B),'coverage_active':fact(B),'year':fact(I),'coinsurance_bps':fact({'type':'integer','minimum':0,'maximum':10000}),'deductible_cents':fact(MONEY),'oop_max_cents':fact(MONEY),'appeal_levels':fact(I)})
provider=obj({'id':S,'name':fact(S),'role':enum('facility','anesthesia','other'),'network':fact(enum('in','out','unknown'))})
service=obj({'id':S,'description':fact(S),'date':fact(DATE),'provider_id':S,'facility_id':fact(S),'submitted_pos':fact(S),'actual_setting':fact(enum('asc','office','hospital','unknown')),'code':fact(S),'code_system':fact(S)})
financial=obj({k:fact(MONEY) for k in ['billed_cents','allowed_cents','paid_cents','member_cents','deductible_cents','copay_cents','coinsurance_cents','adjustment_cents']})
eob=obj({'id':S,'claim_id':fact(S),'service_id':S,'financial':financial,'deductible_used_cents':fact(MONEY),'oop_used_cents':fact(MONEY)})
bill=obj({'id':S,'claim_id':fact(S),'balance_cents':fact(MONEY),'posted_patient_payments_cents':fact(MONEY),'statement_date':fact(DATE),'payment_requested_date':fact(DATE)})
denial=obj({'reason_code':fact(S),'reason':fact(S),'type':fact(enum('network','medical_necessity','authorization','excluded','other','unknown')),'notice_date':fact(DATE),'received_date':fact(DATE),'deadline':fact(DATE),'final_internal':fact(B)})
auth=obj({'id':fact(S),'start':fact(DATE),'end':fact(DATE),'facility_id':fact(S),'scope':fact(S)})
provision=obj({'id':S,'section':S,'topic':S,'evidence_ids':IDS})
question=obj({'id':S,'prompt':S,'why':S,'target_fact_path':S,'status':enum('open','answered','resolved_by_document'),'answer':nullable(S),'evidence_ids':IDS,'blocking_for':IDS})
conclusion=obj({'id':S,'text':S,'classification':enum('fact','interpretation','conditional','unknown'),'outcome':enum('missing_information','possible_provider_error','possible_processing_error','possible_coverage_dispute','likely_correct','requires_escalation'),'evidence_ids':{'type':'array','items':S,'minItems':1},'unresolved':IDS})
claim=schema('claim',obj({'id':S,'revision':{'type':'integer','minimum':1},'as_of':DATE,'synthetic':B,'patient':patient,'plan':plan,'providers':arr(provider),'services':arr(service),'eobs':arr(eob),'bills':arr(bill),'denial':denial,'authorizations':arr(auth),'policy_provisions':arr(provision),'questions':arr(question),'conclusions':arr(conclusion),'corrected_liability_cents':fact(MONEY),'evidence':arr(ref('evidence'))}))
save('schemas/claim.schema.json',claim)
action=obj({'id':S,'owner':enum('member','provider','plan','reviewer'),'title':S,'instructions':S,'status':enum('suggested','draft','user_confirmed_done','blocked'),'due':fact(DATE),'depends_on':IDS,'evidence_ids':{'type':'array','items':S,'minItems':1},'completion_evidence_ids':IDS})
argument=obj({'id':S,'statement':S,'evidence_ids':{'type':'array','items':S,'minItems':1},'limitations':IDS,'requested_remedy':S})
save('schemas/action-plan.schema.json',schema('action-plan',obj({'claim_id':S,'claim_revision':I,'status':enum('draft','needs_information','ready_for_review'),'actions':arr(action),'arguments':arr(argument),'submitted':{'const':False}})))
# Strict evidence anchors refer to supplied authoring pages; extraction probes independently validate against PDF text.
docs=json.loads((R/'demo-case/document-pages.json').read_text());srcs=json.loads((R/'research/sources.json').read_text())
ev=[]
for did,d in docs.items():
 for pnum,p in enumerate(d['pages'],1):
  for section in p['sections']:
   text=section['text'];ev.append({'id':did+':'+section['id'],'domain':'plan' if did=='D01' else 'user','kind':{'D01':'policy','D02':'eob','D03':'denial','D04':'bill','D05':'authorization','D06':'correspondence'}[did],'document_id':did,'source_id':None,'source_url':None,'location':{'page':pnum,'section':section['id'],'start_char':None,'end_char':None,'bbox':None},'text':text,'text_kind':'verbatim','content_sha256':hashlib.sha256(text.encode()).hexdigest(),'verification':'human_reviewed','authority_scope':'Fictional case document; not external authority','accessed_at':None})
for src in srcs:
 if not src['id'].startswith('R'): continue
 text=src['verified_summary'];ev.append({'id':src['id'],'domain':'external','kind':'source_summary','document_id':None,'source_id':src['id'],'source_url':src['url'],'location':{'page':None,'section':src['locator'],'start_char':None,'end_char':None,'bbox':None},'text':text,'text_kind':'verified_paraphrase','content_sha256':hashlib.sha256(text.encode()).hexdigest(),'verification':'human_reviewed','authority_scope':src['jurisdiction'],'accessed_at':src['accessed_date']})
def F(v,ids=[],status='explicit',reason=None,derivation=None): return dict(value=v,status=status,evidence_ids=ids,reason=reason,derivation=derivation)
def U(reason):return F(None,[],'unknown',reason)
def fin(values,e):return {k:F(v,[e]) if v is not None else U('EOB shows -- / not determined') for k,v in zip(['billed_cents','allowed_cents','paid_cents','member_cents','deductible_cents','copay_cents','coinsurance_cents','adjustment_cents'],values)}
q=[dict(id='Q-location',prompt='Where was the anesthesia performed, and can you provide the encounter record?',why='Office versus ASC changes the relevant plan exception.',target_fact_path='services.0.actual_setting',status='open',answer=None,evidence_ids=['D02:E3','D05:A1'],blocking_for=['facility_protection']),dict(id='Q-receipt',prompt='When did you first receive the denial?',why='Needed for the internal appeal filing date.',target_fact_path='denial.received_date',status='open',answer=None,evidence_ids=['D03:N2'],blocking_for=['exact_deadline']),dict(id='Q-payment',prompt='Any payments or newer EOBs since the statement?',why='The bill is only a dated ledger snapshot.',target_fact_path='bills.0.balance_cents',status='open',answer=None,evidence_ids=['D04:B2'],blocking_for=['current_balance'])]
c={'id':'SYN-C260812-A','revision':1,'as_of':'2026-09-24','synthetic':True,'patient':{'member_id':F('SYN-M1042',['D01:P2']),'name':F('Avery Rowan',['D01:P2']),'residence_state':F('CA',['D01:P1'])},'plan':{'id':F('LM-2026-EPO',['D01:P1']),'funding':F('self_funded',['D01:P1']),'erisa':F(True,['D01:P1']),'grandfathered':F(False,['D01:P1']),'coverage_active':F(True,['D01:P2']),'year':F(2026,['D01:P1']),'coinsurance_bps':F(2000,['D01:P4']),'deductible_cents':F(100000,['D01:P4']),'oop_max_cents':F(500000,['D01:P4']),'appeal_levels':F(1,['D01:P13'])},'providers':[{'id':'SYN-P-AN1','name':F('Seabright Anesthesia Group',['D02:E1']),'role':'anesthesia','network':F('out',['D02:E1'])},{'id':'SYN-F-2401','name':F('Juniper Bay Surgery Center',['D02:E5']),'role':'facility','network':F('in',['D02:E5'])}], 'services':[{'id':'SV-A','description':F('Anesthesia associated with knee arthroscopy',['D02:E1']),'date':F('2026-08-12',['D02:E1']),'provider_id':'SYN-P-AN1','facility_id':U('Submitted anesthesia claim has blank facility ID'),'submitted_pos':F('11',['D02:E3']),'actual_setting':F(None,['D02:E3','D02:E5','D05:A1'],'conflicted','Actual anesthesia location needs corroboration'),'code':F('SYN-AN-KNEE',['D02:E1']),'code_system':F('fictional_internal',['D02:E1'])},{'id':'SV-F','description':F('Knee arthroscopy facility services',['D02:E5']),'date':F('2026-08-12',['D02:E5']),'provider_id':'SYN-F-2401','facility_id':F('SYN-F-2401',['D02:E5']),'submitted_pos':F('24',['D02:E5']),'actual_setting':F('asc',['D02:E5']),'code':F('SYN-FAC-KNEE',['D02:E5']),'code_system':F('fictional_internal',['D02:E5'])}], 'eobs':[{'id':'EOB-A','claim_id':F('SYN-C260812-A',['D02:E1']),'service_id':'SV-A','financial':fin([420000,None,0,420000,0,0,0,0],'D02:E2'),'deductible_used_cents':F(100000,['D02:E4']),'oop_used_cents':F(240000,['D02:E4'])},{'id':'EOB-F','claim_id':F('SYN-C260812-F',['D02:E5']),'service_id':'SV-F','financial':fin([1200000,600000,480000,120000,0,0,120000,600000],'D02:E5'),'deductible_used_cents':F(100000,['D02:E6']),'oop_used_cents':F(240000,['D02:E6'])}], 'bills':[{'id':'SYN-B-905','claim_id':F('SYN-C260812-A',['D04:B1']),'balance_cents':F(420000,['D04:B2']),'posted_patient_payments_cents':F(0,['D04:B2']),'statement_date':F('2026-09-05',['D04:B2']),'payment_requested_date':F('2026-10-05',['D04:B2'])}], 'denial':{'reason_code':F('SYN-NET07',['D03:N1']),'reason':F('Non-emergency out-of-network office service',['D03:N1']),'type':F('network',['D03:N1']),'notice_date':F('2026-08-28',['D03:N1']),'received_date':U('Receipt date is absent'),'deadline':U('Receipt date required'),'final_internal':F(False,['D03:N1','D03:N3'])},'authorizations':[{'id':F('SYN-AUTH-771',['D05:A1']),'start':F('2026-08-10',['D05:A1']),'end':F('2026-08-20',['D05:A1']),'facility_id':F('SYN-F-2401',['D05:A1']),'scope':F('One scheduled outpatient knee arthroscopy encounter',['D05:A1'])}],'policy_provisions':[{'id':'P7','section':'7','topic':'network exclusion','evidence_ids':['D01:P7']},{'id':'P8','section':'8','topic':'facility exception','evidence_ids':['D01:P8']},{'id':'P13','section':'13','topic':'internal appeal','evidence_ids':['D01:P13']}],'questions':q,'conclusions':[{'id':'C-location','text':'The records conflict about anesthesia location; investigate before applying the facility exception.','classification':'conditional','outcome':'missing_information','evidence_ids':['D02:E3','D02:E5','D05:A1','D01:P8'],'unresolved':['actual_location','recognized_amount','receipt_date']}],'corrected_liability_cents':U('Recognized amount and corrected adjudication absent'),'evidence':[x for x in ev if x['document_id']!='D06']}
save('demo-case/expected-initial.json',c)
c['revision']=2;c['evidence']=ev
for aid,text in [('U-receipt','I first received the denial on September 1, 2026.'),('U-payment','I have not paid the anesthesia bill.')]:
 c['evidence'].append({'id':aid,'domain':'user_answer','kind':'answer','document_id':None,'source_id':None,'source_url':None,'location':{'page':None,'section':aid,'start_char':None,'end_char':None,'bbox':None},'text':text,'text_kind':'user_statement','content_sha256':hashlib.sha256(text.encode()).hexdigest(),'verification':'unverified','authority_scope':'Presenter statement in fictional case','accessed_at':'2026-09-24'})
c['services'][0]['actual_setting']=F('asc',['D06:L1']);c['services'][0]['facility_id']=F('SYN-F-2401',['D06:L1'])
