 question['status']='resolved_by_document' if question['id']=='Q-location' else 'answered'
 question['answer']={'Q-location':'ASC corroborated by D06','Q-receipt':'2026-09-01 (user-reported)','Q-payment':'No payment (user-reported)'}[question['id']]
 question['evidence_ids']+= {'Q-location':['D06:L1','D06:L3'],'Q-receipt':['U-receipt'],'Q-payment':['U-payment']}[question['id']]
